/* Network owns the program UI; Catalog V2 remains the only equipment/rules store. */
(function(root){
 'use strict';
 const V=root.ND_CATALOG_V2||(typeof require==='function'?require('./catalog-v2.js'):null),states=new Map();
 const isProgram=item=>['worm','heavy_demon'].includes(item?.classId);
 const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const name=item=>item.displayName||item.name||'Неизвестная программа',sign=n=>n<0?'−'+Math.abs(n):'+'+n;
 const type=item=>item.classId==='heavy_demon'?'Тяжёлый Демон':'Червь';
 const uiIcon=id=>root.ND_DOSSIER.uiIcon(id);
 const categoryIcon=kind=>'<img class="network-category-icon" src="assets/network-ui/'+(kind==='demons'?'demon':'worm')+'.png" alt="" width="192" height="192">';
 const active=x=>x.quantity>0&&x.equipped!==false;
 function equipment(c,catalog){return V.normalizeCharacter(c,catalog).equipmentItems.map(instance=>({id:instance.instanceId,instance,item:V.resolve(catalog,instance.catalogId)||instance.snapshot})).filter(x=>x.item);}
 function programRows(c,catalog){return equipment(c,catalog).filter(x=>isProgram(x.item)&&x.instance.quantity>0&&x.instance.location!=='consumed').map(x=>({...x,loaded:x.instance.location==='loaded'&&active(x.instance)}));}
 function model(c,catalog){const stats=V.calculateCharacterStats(c,catalog),all=equipment(c,catalog),rows=programRows(c,catalog),deck=all.find(x=>x.id===stats.deck?.instanceId)||null;const bonus=deck?stats.skills.hacking.sources.filter(x=>x.instanceId===deck.id).reduce((n,x)=>n+x.value,0):0;return {stats,rows,deck,bonus,loaded:rows.filter(x=>x.loaded),library:rows.filter(x=>!x.loaded)};}
 function state(){const key=typeof cloudRecord!=='undefined'&&cloudRecord?.id||'local';if(!states.has(key))states.set(key,{selected:null,hardware:!root.matchMedia?.('(max-width: 767px)').matches,query:'',filter:'all'});return states.get(key);}
 function selected(m,s){if(!m.rows.some(x=>x.id===s.selected))s.selected=m.loaded[0]?.id||null;return m.rows.find(x=>x.id===s.selected)||null;}
 function targetLabel(effect,data){const ids=effect.targetType==='attribute'?V.attributeIds:V.skillIds,list=effect.targetType==='attribute'?data.attributes:data.skills;const i=ids.indexOf(effect.targetId);return i>=0?list[i].name:({max_hp:'Максимум здоровья',armor:'Защита',chrome_capacity:'Вместимость Хрома'})[effect.targetId]||effect.targetId||'';}
 function conditionsText(e,data){const q=e.conditions||{},parts=[];if(q.attributeId)parts.push('Характеристика: '+targetLabel({targetType:'attribute',targetId:q.attributeId},data));if(q.skillId)parts.push('Навык: '+targetLabel({targetType:'skill',targetId:q.skillId},data));if(q.distanceMin!=null||q.distanceMax!=null)parts.push('Дистанция: '+(q.distanceMin??0)+'–'+(q.distanceMax??'∞'));if(q.ownWeapon)parts.push('С собственным оружием');if(q.weaponId)parts.push('Оружие: '+q.weaponId);return parts.join(' · ')||'Условия определяются по описанию';}
 function effectText(e,data){return [Number.isFinite(e.value)?sign(e.value)+' · '+targetLabel(e,data):'',e.description||e.rulesText||e.text||''].filter(Boolean).join(' — ');}
 function effectMarkup(item,data){return (item.effects||[]).map(e=>{const cls=e.type==='conditional_modifier'?'conditional':e.type==='temporary_effect'?'temporary':['stat_modifier','derived_modifier'].includes(e.type)?'permanent':'rules',labels={conditional:'Условный эффект',temporary:'Временный эффект · по описанию',permanent:'Постоянный эффект · при действующем состоянии',rules:'Особые правила'};const text=effectText(e,data);return text?'<div class="network-effect is-'+cls+'"><small>'+labels[cls]+'</small><p>'+h(text)+'</p>'+(cls==='conditional'?'<span>'+h(conditionsText(e,data))+'</span>':'')+'</div>':'';}).join('');}
 // Informational only: conditional/temporary effects never enter permanent totals here.
 function contextEffects(c,catalog,targetType,targetId){const stats=V.calculateCharacterStats(c,catalog);let worms=0,demons=0;return equipment(c,catalog).flatMap(({instance:x,item})=>{if(!active(x)||['inventory','consumed'].includes(x.location))return [];if(isProgram(item)&&x.location==='loaded'){const key=item.classId==='heavy_demon'?'demons':'worms',n=key==='demons'?++demons:++worms;if(!stats.deck||n>stats.programCapacity[key])return [];}return (item.effects||[]).filter(e=>['conditional_modifier','temporary_effect'].includes(e.type)&&e.targetType===targetType&&e.targetId===targetId&&({while_installed:'installed',while_equipped:'equipped',while_loaded:'loaded',while_learned:'learned'})[e.duration]===x.location||e.type==='temporary_effect'&&e.targetType===targetType&&e.targetId===targetId&&x.location===V.stateFor(item)).map(e=>({effect:e,source:name(item),instanceId:x.instanceId}));});}
 function contextMarkup(c,catalog,targetType,targetId,data){return contextEffects(c,catalog,targetType,targetId).map(({effect:e,source})=>'<div class="dossier-context-effect is-'+(e.type==='conditional_modifier'?'conditional':'temporary')+'"><b>'+h(source)+'</b><span>'+h(effectText(e,data))+'</span><small>'+h(e.type==='conditional_modifier'?conditionsText(e,data):'Временный эффект по описанию; автоматически не активирован')+'</small></div>').join('');}
 const image=(item,cls)=>typeof catalogIcon==='function'?catalogIcon(item,cls):'<img class="'+cls+'" src="assets/item-icons/'+(item.classId==='heavy_demon'?'demon':'worm')+'.webp" alt="">';
 function facts(pairs){return '<dl class="network-facts">'+pairs.filter(([,v])=>v!==undefined&&v!==null&&v!=='').map(([k,v])=>'<div><dt>'+h(k)+'</dt><dd>'+h(v)+'</dd></div>').join('')+'</dl>';}
 function meter(kind,count,max){const n=Math.max(0,Math.trunc(max));return '<div class="network-capacity"><div>'+categoryIcon(kind)+'<span><b>'+(kind==='demons'?'Тяжёлые Демоны':'Черви')+'</b><strong>'+count+' / '+max+'</strong></span></div><div class="network-segments" role="img" aria-label="'+(kind==='demons'?'Демоны':'Черви')+': '+count+' из '+max+'">'+(n>0&&n<=12?Array.from({length:n},(_,i)=>'<i class="'+(i<count?'filled':'')+'"></i>').join(''):'<i class="network-proportional" style="--network-fill:'+Math.min(100,max?count/max*100:0)+'%"></i>')+'</div></div>';}
 function deckHeader(m){return `<section class="network-deck-header network-panel" aria-label="Активная нейродека">${m.deck?'<img class="network-deck-art" src="assets/network-ui/deck-hardware.webp" alt="" decoding="async">':'<span class="network-no-device">'+uiIcon('network')+'</span>'}<div class="network-deck-name"><small>${m.deck?'Активная нейродека':'Аппаратная часть'}</small><h2>${m.deck?h(name(m.deck.item)):'Нейродека не установлена'}</h2>${m.deck?'<span class="network-permanent">'+sign(m.bonus)+' Взлом</span>':'<p>Установи устройство через «Снаряжение»</p>'}<span class="network-system-state">${m.deck?'Установлена':'Нет активного устройства'}</span></div>${meter('worms',m.stats.programs.worms,m.stats.programCapacity.worms)}${meter('demons',m.stats.programs.demons,m.stats.programCapacity.demons)}</section>`;}
 function hardware(m){if(!m.deck)return `<section class="network-panel network-hardware"><header class="network-panel-head"><h2>Нейродека / аппаратная часть</h2></header><div class="network-empty">${uiIcon('chrome')}<p>Нейродека не установлена</p><button data-network-inventory>Открыть снаряжение</button></div></section>`;const item=m.deck.item,eq=item.equipment||{},s=state();return `<details class="network-panel network-hardware" id="network-hardware" ${s.hardware?'open':''}><summary class="network-panel-head"><span><b>Нейродека / аппаратная часть</b><small class="network-hardware-summary">${h(name(item))} · Хром ${eq.chromeSlots??item.slots??0}</small></span><span class="network-disclosure" aria-hidden="true">⌄</span></summary><div class="network-hardware-body"><div class="network-circuit"><img src="assets/network-ui/deck-circuit.webp" alt="Аппаратный модуль нейродеки" decoding="async"></div>${facts([['Модель',name(item)],['Бонус',sign(m.bonus)+' Взлом'],['Слоты Хрома',eq.chromeSlots??item.slots],['Черви',eq.wormCapacity],['Тяжёлые Демоны',eq.demonCapacity],['Защита / контр-ICE',item.stats?.defense],['Производитель',item.manufacturer]])}<div class="network-hardware-rules">${item.description?'<p>'+h(item.description)+'</p>':''}${item.rulesText&&item.rulesText!==item.description?'<p>'+h(item.rulesText)+'</p>':''}${effectMarkup(item,D)}<button data-network-inventory>Открыть снаряжение</button></div></div></details>`;}
 function row(x,m){const params=[['Цель',x.item.stats?.target??x.item.target],['СЛ',x.item.stats?.difficulty??x.item.difficulty]].filter(([,v])=>v!=null&&v!=='');return `<button type="button" class="network-program ${state().selected===x.id?'is-selected':''}" data-network-select="${h(x.id)}" aria-pressed="${state().selected===x.id}">${image(x.item,'network-program-icon')}<span class="network-program-copy"><strong>${h(name(x.item))}</strong><small class="network-loaded">✓ Загружен</small>${params.length?'<span class="network-program-params">'+params.map(([k,v])=>h(k)+': '+h(v)).join(' · ')+'</span>':''}</span><span class="network-type">${x.item.classId==='heavy_demon'?'Демон':'Червь'}</span><span aria-hidden="true" class="network-arrow">›</span></button>`;}
 function group(m,kind){const cls=kind==='demons'?'heavy_demon':'worm',rows=m.loaded.filter(x=>x.item.classId===cls),capacity=m.stats.programCapacity[kind],free=Math.max(0,capacity-rows.length);return `<section class="network-program-group"><header>${categoryIcon(kind)}<h3>${kind==='demons'?'Тяжёлые Демоны':'Черви'} <small>${rows.length} / ${capacity}</small></h3></header><div class="network-program-rows">${rows.map(x=>row(x,m)).join('')}${free?'<button class="network-free-slot" data-network-manage><span aria-hidden="true">＋</span><span>Свободно слотов: '+free+'<small>Доступно для загрузки</small></span></button>':!rows.length?'<p class="network-group-empty">'+(m.deck?'Нет загруженных программ':'Загрузка недоступна без нейродеки')+'</p>':''}</div></section>`;}
 function programs(m){return `<section class="network-panel network-programs"><header class="network-panel-head"><h2>Загруженные программы</h2><small>${m.loaded.length} / ${m.stats.programCapacity.worms+m.stats.programCapacity.demons}</small></header><div class="network-programs-content">${group(m,'worms')}${group(m,'demons')}<button class="network-manage" data-network-manage>${uiIcon('import')}<span>Управлять программами</span></button>${m.deck&&!m.rows.length&&canEdit?'<button class="network-add-empty" data-network-catalog>Добавить программы</button>':''}<small class="network-load-hint">Загрузка программы не означает её запуск</small></div></section>`;}
 function detail(x){if(!x)return `<aside class="network-panel network-detail"><header class="network-panel-head"><h2>Данные программы</h2></header><div class="network-empty">${uiIcon('network')}<p>Выбери программу в списке или библиотеке</p></div></aside>`;const item=x.item,st=item.stats||{},eq=item.equipment||{};return `<aside class="network-panel network-detail" aria-labelledby="network-detail-title"><header class="network-panel-head"><h2>Данные программы</h2></header><div class="network-detail-content"><div class="network-detail-identity">${image(item,'network-detail-icon')}<div><h3 id="network-detail-title">${h(name(item))}</h3><span class="network-type">${type(item)}</span><small>${x.loaded?'Загружена':'В библиотеке'}</small>${item.archived?'<small>Архив · сохранённый экземпляр</small>':''}</div></div>${facts([['Цель',st.target??item.target],['Сложность',st.difficulty??item.difficulty],['Стоимость активации',st.activationCost??eq.activationCost],['Длительность',st.duration],['Дальность, гексы',st.rangeMax],['Урон',st.damage],['Расход Драйва',st.driveCost],['Тип действия',st.action],['Ограничения',item.availability?.restrictions]])}${item.description?'<section class="network-rule-section"><h4>Эффект и описание</h4><p>'+h(item.description)+'</p></section>':''}${effectMarkup(item,D)}${item.rulesText&&item.rulesText!==item.description?'<section class="network-rule-section"><h4>Особые правила</h4><p>'+h(item.rulesText)+'</p></section>':''}</div></aside>`;}
 function renderNetwork(){const m=model(card,D.catalog),s=state(),x=selected(m,s);return `<div class="network-ui">${deckHeader(m)}${m.stats.issues.length?'<div class="network-warning" role="status">'+m.stats.issues.map(t=>'<p>'+h(t)+'</p>').join('')+'</div>':''}<div class="network-workspace">${hardware(m)}${programs(m)}${detail(x)}</div><details class="network-panel network-capabilities"><summary>${uiIcon('network')}<b>Сетевые возможности</b></summary><p>Раздел в разработке</p></details></div>`;}
 function requireEdit(){if(!canEdit)throw Error('Карточка доступна только для просмотра');}
 function owned(id){const x=programRows(card,D.catalog).find(x=>x.id===id);if(!x)throw Error('Программа не найдена');return x;}
 function addProgram(id){requireEdit();const item=V.resolve(D.catalog,id);if(!isProgram(item))throw Error('Выбери Червя или Тяжёлого Демона');const next=V.addEquipment(card,D.catalog,id,1);state().selected=next.equipmentItems.at(-1).instanceId;root.ND_SHEET_V2.commit(next);}
 function changeProgram(id,load){requireEdit();const x=owned(id),m=model(card,D.catalog);if(load===x.loaded)return;if(load){if(!m.deck)throw Error('Для загрузки нужна установленная нейродека');const key=x.item.classId==='heavy_demon'?'demons':'worms';if(m.stats.programs[key]>=m.stats.programCapacity[key])throw Error('Нет свободных слотов: '+(key==='demons'?'Тяжёлые Демоны':'Черви'));}root.ND_SHEET_V2.commit(V.setEquipmentState(card,D.catalog,id,load?'loaded':'inventory'));}
 function removeProgram(id){requireEdit();owned(id);root.ND_SHEET_V2.commit(V.removeEquipment(card,D.catalog,id));}
 function pick(id){if(!model(card,D.catalog).rows.some(x=>x.id===id))return;state().selected=id;render();}
 function managerRow(x,m){const key=x.item.classId==='heavy_demon'?'demons':'worms',canLoad=!!m.deck&&m.stats.programs[key]<m.stats.programCapacity[key];return `<article class="network-library-row">${image(x.item,'network-program-icon')}<div><strong>${h(name(x.item))}</strong><small>${type(x.item)}${x.item.archived?' · Архив':''}</small><button data-network-inspect="${h(x.id)}">Подробности</button></div>${canEdit?`<div class="network-library-actions"><button data-network-toggle="${h(x.id)}" ${!x.loaded&&!canLoad?'disabled':''}>${x.loaded?'Выгрузить':'Загрузить'}</button><button class="network-delete" data-network-delete="${h(x.id)}" aria-label="Удалить из библиотеки: ${h(name(x.item))}">Удалить из библиотеки</button></div>`:''}</article>`;}
 function manager(){const m=model(card,D.catalog);modal('Программы нейродеки',`<div class="network-manager" data-network-manager><p class="network-manager-capacity">Черви ${m.stats.programs.worms} / ${m.stats.programCapacity.worms} · Тяжёлые Демоны ${m.stats.programs.demons} / ${m.stats.programCapacity.demons}</p>${!m.deck?'<p>Нейродека не установлена. Библиотека доступна, загрузка отключена.</p>':''}<h3>Загружено</h3>${m.loaded.map(x=>managerRow(x,m)).join('')||'<p class="network-manager-empty">Загруженных программ нет</p>'}<h3>Библиотека</h3>${m.library.map(x=>managerRow(x,m)).join('')||'<p class="network-manager-empty">Библиотека пуста</p>'}${canEdit?'<button class="yellow" data-network-catalog>+ Добавить из справочника</button>':''}</div>`);$('#dialog').classList.add('network-dialog');bindManager();}
 function bindManager(){document.querySelectorAll('[data-network-inspect]').forEach(b=>b.onclick=()=>{closeModal();pick(b.dataset.networkInspect);document.querySelector('#network-detail-title')?.scrollIntoView?.({block:'nearest',behavior:'auto'});});document.querySelectorAll('[data-network-toggle]').forEach(b=>b.onclick=()=>{if(!canEdit)return;try{const x=owned(b.dataset.networkToggle);changeProgram(x.id,!x.loaded);manager();}catch(e){error(e);}});document.querySelectorAll('[data-network-delete]').forEach(b=>b.onclick=()=>{if(!canEdit)return;const x=owned(b.dataset.networkDelete);modal('Удалить программу из библиотеки?',`<div class="network-manager"><p>${h(name(x.item))}</p><p>Программа будет удалена из владения. Для сохранения программы используй выгрузку.</p><button id="network-confirm-delete" class="danger">Удалить программу</button><button id="network-cancel-delete">Отмена</button></div>`);$('#network-cancel-delete').onclick=manager;$('#network-confirm-delete').onclick=()=>{if(!canEdit)return;try{removeProgram(x.id);manager();}catch(e){error(e);}};});document.querySelectorAll('[data-network-catalog]').forEach(b=>b.onclick=catalogDialog);}
 function catalogDialog(){if(!canEdit)return;const s=state();modal('Добавить программу из справочника',`<div class="network-manager network-catalog"><p>Добавление не списывает эдди. Загрузка выполняется отдельно.</p><div class="network-catalog-tools"><label>Поиск<input id="network-catalog-search" type="search" placeholder="Название программы" value="${h(s.query)}"></label><label>Тип<select id="network-catalog-filter"><option value="all">Все программы</option><option value="worm" ${s.filter==='worm'?'selected':''}>Черви</option><option value="heavy_demon" ${s.filter==='heavy_demon'?'selected':''}>Тяжёлые Демоны</option></select></label></div><div id="network-catalog-results"></div><button id="network-back-library">Вернуться в библиотеку</button></div>`);$('#dialog').classList.add('network-dialog');const fill=()=>{s.query=$('#network-catalog-search').value;s.filter=$('#network-catalog-filter').value;const q=s.query.trim().toLocaleLowerCase('ru');const rows=V.all(D.catalog).filter(x=>isProgram(x)&&!x.archived&&(s.filter==='all'||x.classId===s.filter)&&name(x).toLocaleLowerCase('ru').includes(q));$('#network-catalog-results').innerHTML=rows.map(item=>`<article class="network-catalog-row">${image(item,'network-program-icon')}<div><strong>${h(name(item))}</strong><small>${type(item)}</small><p>${h(item.description)}</p>${item.rulesText&&item.rulesText!==item.description?'<details><summary>Особые правила</summary><p>'+h(item.rulesText)+'</p></details>':''}</div><button data-network-add="${h(item.catalogId)}">Добавить</button></article>`).join('')||'<p>Подходящих программ нет</p>';document.querySelectorAll('[data-network-add]').forEach(b=>b.onclick=()=>{if(!canEdit)return;try{addProgram(b.dataset.networkAdd);manager();notify('Программа добавлена в библиотеку');}catch(e){error(e);}});};$('#network-catalog-search').oninput=fill;$('#network-catalog-filter').onchange=fill;$('#network-back-library').onclick=manager;fill();$('#network-catalog-search').focus();}
 function bind(){document.querySelectorAll('[data-network-select]').forEach(b=>b.onclick=()=>{pick(b.dataset.networkSelect);document.querySelector('.network-program.is-selected')?.focus();});document.querySelectorAll('[data-network-manage]').forEach(b=>b.onclick=manager);document.querySelectorAll('[data-network-catalog]').forEach(b=>b.onclick=catalogDialog);document.querySelectorAll('[data-network-inventory]').forEach(b=>b.onclick=()=>switchSheetTab('inventory'));const hd=$('#network-hardware');if(hd)hd.ontoggle=()=>{state().hardware=hd.open;};}
 const api={render:renderNetwork,bind,model,programRows,isProgram,contextEffects,contextMarkup,effectMarkup,conditionsText,state,addProgram,changeProgram,removeProgram,manager,catalogDialog};root.ND_NETWORK=api;if(typeof module==='object'&&module.exports)module.exports=api;
})(typeof window==='object'?window:globalThis);
